def transform(grid):
    h, w = len(grid), len(grid[0])
    motifs = []

    # A motif is a solid 1x1, 2x2, or 3x3 center surrounded by a uniform
    # nonzero frame color. Missing sides are allowed only where the grid itself
    # ends, to handle cropped motifs at the right/bottom edges.
    for size in (1, 2, 3):
        for y0 in range(h - size + 1):
            for x0 in range(w - size + 1):
                color = grid[y0][x0]
                if color == 0 or any(
                    grid[y][x] != color
                    for y in range(y0, y0 + size)
                    for x in range(x0, x0 + size)
                ):
                    continue
                frame_colors = set()
                directions = 0
                if y0 > 0:
                    directions += 1
                    frame_colors.update(grid[y0 - 1][x] for x in range(x0, x0 + size))
                if y0 + size < h:
                    directions += 1
                    frame_colors.update(grid[y0 + size][x] for x in range(x0, x0 + size))
                if x0 > 0:
                    directions += 1
                    frame_colors.update(grid[y][x0 - 1] for y in range(y0, y0 + size))
                if x0 + size < w:
                    directions += 1
                    frame_colors.update(grid[y][x0 + size] for y in range(y0, y0 + size))
                if len(frame_colors) == 1 and color not in frame_colors and directions >= 2:
                    frame = next(iter(frame_colors))
                    if frame != 0:
                        motifs.append((y0, y0 + size - 1, x0, x0 + size - 1, color))

    # De-duplicate any same rectangle found more than once.
    motifs = list(dict.fromkeys(motifs))
    if not motifs:
        return [row[:] for row in grid]

    common = Counter(m[4] for m in motifs).most_common(1)[0][0]
    marks = [m for m in motifs if m[4] != common]
    out = [row[:] for row in grid]

    # Join equal-colored marked centers along aligned rows/columns, painting
    # only the empty cells between them.
    for i, (y0, y1, x0, x1, color) in enumerate(marks):
        for yy0, yy1, xx0, xx1, other in marks[i + 1:]:
            if color != other:
                continue
            if y0 == yy0 and y1 == yy1 and (x1 < xx0 or xx1 < x0):
                left, right = (x1, xx0) if x1 < xx0 else (xx1, x0)
                for y in range(y0, y1 + 1):
                    for x in range(left + 1, right):
                        if out[y][x] == 0:
                            out[y][x] = color
            elif x0 == xx0 and x1 == xx1 and (y1 < yy0 or yy1 < y0):
                top, bottom = (y1, yy0) if y1 < yy0 else (yy1, y0)
                for y in range(top + 1, bottom):
                    for x in range(x0, x1 + 1):
                        if out[y][x] == 0:
                            out[y][x] = color
